# =============================================================================
# 08_latex_tables.R
#
# PURPOSE: Convert final CSV output tables into controlled LaTeX tables for the
#          report appendix. This avoids overly wide auto-generated CSV tables.
# =============================================================================

escape_latex <- function(x) {
  x <- as.character(x)
  x <- gsub("\\\\", "\\\\textbackslash{}", x)
  x <- gsub("([&_#%{}])", "\\\\\\1", x, perl = TRUE)
  x
}

write_rows <- function(df, cols, con) {
  for (i in seq_len(nrow(df))) {
    vals <- escape_latex(df[i, cols])
    writeLines(paste0(paste(vals, collapse = " & "), " \\\\"), con)
  }
}

write_appendix_tables <- function(
    table_dir = "output/tables",
    out_file  = "output/tables/appendix_tables.tex"
) {
  table1 <- read.csv(file.path(table_dir, "table1_ari_by_proximity_rate.csv"),
                     check.names = FALSE)
  table2 <- read.csv(file.path(table_dir, "table2_ari_by_clustering_method.csv"),
                     check.names = FALSE)
  table3 <- read.csv(file.path(table_dir, "table3_zero_overlap_pairs.csv"),
                     check.names = FALSE)

  con <- file(out_file, open = "w")
  on.exit(close(con), add = TRUE)

  writeLines(c(
    "% Auto-generated by R/08_latex_tables.R",
    "\\subsection{ARI by Proximity Measure and Missingness Rate}",
    "\\begin{landscape}",
    "\\begin{center}",
    "\\small",
    "\\begin{longtable}{@{}llcccc@{}}",
    "\\caption{Mean (SD) ARI by data type, proximity measure, and missingness rate.}\\\\",
    "\\toprule",
    "Data Type & Proximity Measure & 0\\% & 10\\% & 30\\% & 50\\% \\\\",
    "\\midrule",
    "\\endfirsthead",
    "\\toprule",
    "Data Type & Proximity Measure & 0\\% & 10\\% & 30\\% & 50\\% \\\\",
    "\\midrule",
    "\\endhead"
  ), con)
  write_rows(table1, names(table1), con)
  writeLines(c("\\bottomrule", "\\end{longtable}", "\\end{center}", "\\end{landscape}", ""), con)

  writeLines(c(
    "\\subsection{ARI by Proximity Measure and Clustering Method}",
    "\\begin{landscape}",
    "\\begin{center}",
    "\\small",
    "\\begin{longtable}{@{}llcc@{}}",
    "\\caption{Mean (SD) ARI by data type, proximity measure, and clustering method.}\\\\",
    "\\toprule",
    "Data Type & Proximity Measure & PAM & UPGMA \\\\",
    "\\midrule",
    "\\endfirsthead",
    "\\toprule",
    "Data Type & Proximity Measure & PAM & UPGMA \\\\",
    "\\midrule",
    "\\endhead"
  ), con)
  write_rows(table2, names(table2), con)
  writeLines(c("\\bottomrule", "\\end{longtable}", "\\end{center}", "\\end{landscape}", ""), con)

  writeLines(c(
    "\\subsection{No-Overlap Pair Diagnostics}",
    "\\begin{landscape}",
    "\\begin{center}",
    "\\tiny",
    "\\setlength{\\tabcolsep}{3pt}",
    "\\begin{longtable}{@{}p{0.7in}p{0.65in}p{0.55in}p{0.55in}p{1.25in}p{0.75in}p{0.75in}p{0.75in}@{}}",
    "\\caption{Mean no-overlap pair diagnostics by condition and proximity measure.}\\\\",
    "\\toprule",
    "Data & Sep. & Mech. & Rate & Proximity & Mean Prop. & SD Prop. & Mean Count \\\\",
    "\\midrule",
    "\\endfirsthead",
    "\\toprule",
    "Data & Sep. & Mech. & Rate & Proximity & Mean Prop. & SD Prop. & Mean Count \\\\",
    "\\midrule",
    "\\endhead"
  ), con)
  write_rows(table3, names(table3), con)
  writeLines(c("\\bottomrule", "\\end{longtable}", "\\end{center}", "\\end{landscape}"), con)

  invisible(out_file)
}

write_appendix_tables()
